test('invoiceTotals calculates VAT on discounted amount', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 10 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line total: 100*1000 = 100000
  // Discount: 10% = 10000
  // Amount after discount: 90000
  // VAT: 21% of 90000 = 18900
  // Total: 100000 - 10000 + 18900 = 108900
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 10000);
  assert.equal(totals.vat, 18900);
  assert.equal(totals.total, 108900);
});

